for p in D.glob('*.json'):
 if p.stem=='manifest':continue
 b=json.loads(p.read_text())
 for q in b:
  for o in q['options']:
   if o['label']==q['answer'] and o['text'] in M:o['text']=M[o['text']]
 p.write_text(json.dumps(b,ensure_ascii=False,indent=2)+'\n')
